+      for (const value of invalid) {
+        assert.throws(() => nextRetry({ ...base, retryable, [field]: value }), Error);
+      }
+    }
+  }
+});
+
+test('handles frozen input, ignored extras, uncapped hints, and inclusive budgets', () => {
+  assert.deepEqual(nextRetry(Object.freeze({ ...base, extra: 'ignored' })), scheduled(10));
+  assert.deepEqual(nextRetry({ ...base, attempt: 3 }), scheduled(40));
+  assert.deepEqual(nextRetry({ ...base, attempt: 9 }), scheduled(100));
+  assert.deepEqual(nextRetry({ ...base, retryAfterMs: 150 }), scheduled(150));
+  assert.deepEqual(nextRetry({ ...base, retryAfterMs: 1 }), scheduled(10));
+  assert.deepEqual(nextRetry({ ...base, elapsedMs: 990 }), scheduled(10));
+  assert.deepEqual(nextRetry({ ...base, elapsedMs: 991 }), exhausted);
+  assert.deepEqual(nextRetry({ ...base, elapsedMs: 1001, baseMs: 0 }), exhausted);
+  assert.deepEqual(nextRetry({ ...base, elapsedMs: 1000, baseMs: 0 }), scheduled(0));
+  assert.deepEqual(nextRetry({ ...base, retryAfterMs: 1001 }), exhausted);
+});
+
+test('caps huge attempts safely and preserves zero bases', () => {
+  const max = Number.MAX_SAFE_INTEGER;
+  for (const attempt of [53, 54, 1025, max]) {
+    assert.deepEqual(nextRetry({ ...base, attempt, baseMs: 0 }), scheduled(0));
+    assert.deepEqual(nextRetry({ ...base, attempt }), scheduled(100));
+  }
+  assert.deepEqual(nextRetry({ ...base, attempt: 53, baseMs: 1, maxDelayMs: max, budgetMs: max }), scheduled(2 ** 52));
+  assert.deepEqual(nextRetry({ ...base, attempt: max, maxDelayMs: max, budgetMs: max }), scheduled(max));
+  assert.deepEqual(nextRetry({ ...base, maxDelayMs: 0 }), scheduled(0));
+  assert.deepEqual(nextRetry({ ...base, elapsedMs: max, budgetMs: max }), exhausted);
+});
+
+test('CLI obeys output and exit contracts and imports silently', () => {
+  const dir = mkdtempSync(join(tmpdir(), 'retry-budget-'));
+  const script = fileURLToPath(new URL('../retry-budget.js', import.meta.url));
+  const input = join(dir, 'input.json');
+  const run = args => spawnSync(process.execPath, [script, ...args], { encoding: 'utf8', cwd: dir });
+  const failure = args => {
+    const result = run(args);
+    assert.equal(result.status, 2);
+    assert.equal(result.stdout, '');
+    assert.ok(result.stderr.length > 0);
+  };
+  try {
+    for (const options of [base, { ...base, retryable: false }, { ...base, budgetMs: 0 }]) {
+      writeFileSync(input, JSON.stringify(options));
+      const result = run([input]);
+      assert.equal(result.status, 0);
+      assert.equal(result.stderr, '');
+      assert.equal(result.stdout, `${JSON.stringify(nextRetry(options))}\n`);
+    }
+    failure([]);
+    failure([input, input]);
+    failure([join(dir, 'missing.json')]);
+    failure([dir]);
+    for (const value of ['{', 'null', '[]', '{}', JSON.stringify({ ...base, retryable: 'false' })]) {
+      writeFileSync(input, value);
+      failure([input]);
+    }
+    const imported = spawnSync(process.execPath, ['--input-type=module', '-e',
+      `import ${JSON.stringify(new URL('../retry-budget.js', import.meta.url).href)}`],
+    { encoding: 'utf8', cwd: dir });
+    assert.equal(imported.status, 0);
+    assert.equal(imported.stdout, '');
+    assert.equal(imported.stderr, '');
+  } finally {
+    rmSync(dir, { recursive: true, force: true });
+  }
+});
